import {TILES,ROLES} from './engine.js?v=0.8.0';
import {esc,tileCard} from './tile-ui.js?v=0.8.0';
export const number=n=>new Intl.NumberFormat('fr-CA',{maximumFractionDigits:1}).format(n||0);
const sum=(a,k)=>a.reduce((n,r)=>n+(r[k]||0),0);
const metric=(n,label,cls='')=>`<div class="stat-sticker ${cls}"><b>${number(n)}</b><span>${label}</span></div>`;
export function songRows(game,playerId='band',range='all'){
 return (game.songs||[]).filter(s=>range==='all'||s.show===game.show&&s.attempt===game.attempt).map((s,i)=>{const ps=s.players.filter(p=>playerId==='band'||p.id===playerId);return {label:`N${s.show+1} · E${s.attempt+1} · T${s.round}`,index:i+1,...Object.fromEntries(['q','e','f','bonusFans','fans','tiles','links','repeats','empty','inactive','inventory'].map(k=>[k,sum(ps,k)])),maxMultiplier:Math.max(1,...ps.map(p=>p.maxMultiplier)),heat:Array.from({length:9},(_,i)=>ps.reduce((n,p)=>n+(p.heat?.[i]||0),0)),players:ps};});
}
export function series(rows,key,mode){let total=0;return rows.map((r,i)=>{const value=r[key]+(key==='f'?r.bonusFans:0);total+=value;return mode==='cumulative'?(key==='f'?r.fans:total):mode==='velocity'?(i?value-(rows[i-1][key]+(key==='f'?rows[i-1].bonusFans:0)):null):value;});}
function chart(rows,key,label,mode){
 const values=series(rows,key,mode),valid=values.filter(v=>v!==null);if(!valid.length)return `<section class="chart-panel metric-${key}"><h3>${label}</h3><p>Deux tounes pour mesurer l’accélération.</p></section>`;
 const low=Math.min(0,...valid),high=Math.max(1,...valid),span=high-low,x=i=>40+i*360/Math.max(1,values.length-1),y=v=>142-(v-low)/span*112;
 const line=values.map((v,i)=>v===null?'':`${x(i)},${y(v)}`).filter(Boolean).join(' '),latest=valid.at(-1);
 return `<section class="chart-panel metric-${key}"><h3>${label}<b>${mode==='velocity'&&latest>0?'+':''}${number(latest)}</b></h3><svg class="song-chart" viewBox="0 0 430 173" role="img" aria-label="${label} : ${esc(values.map((v,i)=>rows[i].label+' '+(v===null?'non disponible':number(v))).join(', '))}">${[low,(low+high)/2,high].map(v=>`<line x1="40" x2="405" y1="${y(v)}" y2="${y(v)}" class="chart-guide"/><text x="34" y="${y(v)+4}" text-anchor="end">${number(v)}</text>`).join('')}<polyline points="${line}"/>${values.map((v,i)=>v===null?'':`<circle cx="${x(i)}" cy="${y(v)}" r="${values.length>60?2:4}"><title>${esc(rows[i].label)} : ${number(v)}</title></circle>`).join('')}<text x="40" y="165">${esc(rows[0].label)}</text><text x="404" y="165" text-anchor="end">${esc(rows.at(-1).label)}</text></svg></section>`;
}
export function statsMarkup(game,{playerId='band',range='all',chartMode='production'}={}){
 const selected=game.players.find(p=>p.id===playerId),people=selected?[selected]:game.players,rows=songRows(game,playerId,range),careers=people.map(p=>p.career).filter(Boolean),all=range==='all';
 const source=all?careers:rows,total=k=>sum(source,k),songs=all?Math.max(0,...careers.map(c=>c.songs)):rows.length;
 const fans=all?sum(people,'fans'):sum(rows,'f')+sum(rows,'bonusFans'),q=total('q'),e=total('e'),heat=Array.from({length:9},(_,i)=>source.reduce((n,r)=>n+(r.heat?.[i]||0),0)),maxHeat=Math.max(1,...heat),peak=Math.max(1,...source.map(r=>r.maxMultiplier||1));
 const ranking={};for(const r of (all?careers:rows.flatMap(r=>r.players)))for(const [kind,t] of Object.entries(r.byTile||{})){const a=ranking[kind]??={appearances:0,q:0,e:0,f:0};for(const k of Object.keys(a))a[k]+=t[k];}
 const top=Object.entries(ranking).sort((a,b)=>(b[1].q+b[1].e)-(a[1].q+a[1].e)).slice(0,5),best=rows.reduce((a,r)=>!a||r.q+r.e>a.q+a.e?r:a,null),split=Math.round(q/Math.max(1,q+e)*100);
 const history=(game.history||[]).filter(h=>all||h.show===game.show&&h.attempt===game.attempt);
 return `<section class="stats-screen"><span class="tape">${game.phase==='reward'?'LE RAPPORT APRÈS LE VACARME':'DISQUE LIVE · TOURNÉE EN COURS'}</span><h1>${selected?esc(selected.name):'LE BAND.<br>LE BRUIT.<br>LES CHIFFRES.'}</h1>
 <div class="stats-tabs" aria-label="Profil"><button data-action="stats-player" data-id="band" class="${!selected?'active':''}">LE BAND</button>${game.players.map(p=>`<button data-action="stats-player" data-id="${esc(p.id)}" class="${selected?.id===p.id?'active':''}">${esc(p.name)}</button>`).join('')}</div>
 ${selected?`<div class="profile-hero"><img src="./art/guitarist-singer.png" alt="Portrait de classe"><div><span>CLASSE</span><h2>${esc(ROLES[selected.role]?.name||selected.role)}</h2><p>${selected.inventory.length} tuiles · ${selected.focusBase||1} focus de base</p><strong>${number(selected.fans)} FANS</strong></div></div>`:''}
 <div class="stats-tabs"><button data-action="stats-range" data-range="all" class="${all?'active':''}">TOUTE LA TOURNÉE</button><button data-action="stats-range" data-range="show" class="${!all?'active':''}">CE SHOW</button></div>
 <div class="stats-headliners">${metric(fans,all?'FANS CUMULÉS':'NOUVEAUX FANS','pink')}${metric(songs,'TOUNES ENREGISTRÉES')}${metric(q,'QUALITÉ','cyan')}${metric(e,'ÉNERGIE','orange')}</div>
 ${!songs?'<p class="stats-empty">Le tape roule. Joue une toune pour faire péter les compteurs !</p>':`<div class="stats-awards"><span>BRISEUR D’AMPLI <b>×${peak}</b><small>Meilleur multiplicateur</small></span><span>MACHINE À BRUIT <b>${number((q+e)/songs)}</b><small>Qualité + énergie / toune</small></span><span>COLLE À BAND <b>${number(total('links'))}</b><small>Liens d’effets activés</small></span></div>
 <h2>LE SISMOGRAPHE</h2><div class="stats-tabs">${[['production','PAR TOUNE'],['cumulative','CUMUL'],['velocity','ACCÉLÉRATION']].map(([k,l])=>`<button data-action="stats-mode" data-mode="${k}" class="${chartMode===k?'active':''}">${l}</button>`).join('')}</div><p class="stats-note">${chartMode==='velocity'?'Écart avec la toune précédente. Au-dessus de zéro : ça accélère !':chartMode==='cumulative'?'Qualité et énergie cumulées sur les tounes affichées. Fans : total réel à chaque toune.':'Production de chaque toune. Les fans de performance sont attribués à la dernière toune du show.'} Chaque courbe a sa propre échelle.</p>
 ${[['q','QUALITÉ'],['e','ÉNERGIE'],['f','FANS']].map(([k,l])=>chart(rows,k,l,chartMode)).join('')}
 <div class="stats-duo"><section class="chart-panel"><h3>TON ADN SONORE</h3><div class="sound-donut" style="--split:${split}%"><b>${split}%<small>QUALITÉ</small></b></div><p class="stats-note">${split}% qualité · ${100-split}% énergie</p></section><section class="chart-panel"><h3>LE COIN QUI TORCHE</h3><div class="heat-grid">${heat.map((n,i)=>`<span style="--heat:${.12+.88*n/maxHeat}" title="Case ${i+1} : ${number(n)} qualité + énergie">${number(n)}</span>`).join('')}</div><p class="stats-note">Qualité + énergie par case. Plus c’est vif, plus ça produit.</p></section></div>
 ${!selected?`<section class="chart-panel"><h3>QUI FAIT TREMBLER LES MURS ?</h3>${['q','e','fans'].map((k,ki)=>{const vals=game.players.map(p=>{const rr=rows.flatMap(r=>r.players).filter(r=>r.id===p.id);return all?(k==='fans'?p.fans:p.career?.[k]||0):(k==='fans'?sum(rr,'f')+sum(rr,'bonusFans'):sum(rr,k));}),den=vals.reduce((a,b)=>a+b,0);return `<p class="contribution-label">${['QUALITÉ','ÉNERGIE','FANS'][ki]}</p><div class="contribution-bar">${vals.map((v,i)=>`<i style="width:${den?v/den*100:100/vals.length}%;--member:${i}"></i>`).join('')}</div><div class="contribution-legend">${game.players.map((p,i)=>`<span>${esc(p.name)} <b>${number(vals[i])}</b> (${den?Math.round(vals[i]/den*100):0}%)</span>`).join('')}</div>`;}).join('')}</section>`:''}
 <h2>LES TUILES VEDETTES</h2><p class="stats-note">Classées par qualité + énergie réellement produites, redéclenchements inclus. Les tuiles de soutien aident les autres sans récupérer leurs points.</p><div class="tile-ranking">${top.map(([kind,t],i)=>`<div><b class="rank">${i+1}</b>${tileCard({kind},{action:'inspect-offer',attributes:`data-kind="${kind}"`})}<span><strong>${number(t.q+t.e)} POINTS</strong><small>${number(t.q)} qualité · ${number(t.e)} énergie<br>${t.f} fans · ${t.appearances} apparitions<br>${number((t.q+t.e)/t.appearances)} points / apparition</small></span></div>`).join('')}</div>
 <div class="stats-headliners">${metric(total('repeats'),'REDÉCLENCHEMENTS')}${metric(total('tiles'),'TUILES ACTIVES JOUÉES','cyan')}${metric(total('f'),'FANS DES TUILES','pink')}${metric(total('bonusFans'),'FANS DE PERFORMANCE','orange')}${metric(all?Math.max(0,...careers.map(c=>c.bestQ)):Math.max(0,...rows.map(r=>r.q)),'RECORD QUALITÉ*')}${metric(all?Math.max(0,...careers.map(c=>c.bestE)):Math.max(0,...rows.map(r=>r.e)),'RECORD ÉNERGIE*')}</div><p class="stats-note">* ${all&&!selected?'Meilleure production individuelle en une toune.':'Meilleure production en une toune.'}</p>
 ${best?`<div class="encore-award">LA TOUNE QUI A DÉVISSÉ LE PLAFOND<b>${number(best.q+best.e)} POINTS</b><span>${esc(best.label)} · parmi les tounes affichées</span></div>`:''}
 <details class="song-ledger"><summary>LE TAPE COMPLET · ${rows.length} TOUNES</summary><div class="ledger-scroll"><table><thead><tr><th>Toune</th><th>Qualité</th><th>Énergie</th><th>Fans +</th><th>Fans ∑</th><th>Liens</th><th>× max</th><th>Vides</th><th>Inactives</th><th>Inventaire</th></tr></thead><tbody>${rows.map(r=>`<tr><th>${esc(r.label)}</th>${[r.q,r.e,r.f+r.bonusFans,r.fans,r.links,r.maxMultiplier,r.empty,r.inactive,r.inventory].map(v=>`<td>${number(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`}
 <details class="song-ledger"><summary>LES SALLES CONQUISES · ${history.filter(h=>h.won).length}/${history.length}</summary>${history.map(h=>`<div class="show-stamp"><b>${h.won?'ÇA A BRASSÉ !':'ON REVIENDRA !'}</b><span>Niveau ${h.show+1} · Essai ${(h.attempt||0)+1}</span><span>Qualité ${number(h.q)} / ${number(h.target?.q)} · Énergie ${number(h.e)} / ${number(h.target?.e)}</span></div>`).join('')||'<p>Termine un show pour accrocher ton premier souvenir.</p>'}</details>
 <p class="stats-note">${game.songs?.length===250?'Graphiques : 250 dernières tounes. Les compteurs de carrière conservent tout. ':''}Les anciennes tounes sans enregistrement détaillé ne sont pas reconstituées. Les fans cumulés restent conservés.</p><button class="primary" data-action="back">RETOUR SUR SCÈNE</button><button class="secondary" data-action="quit">RETOUR À L’ACCUEIL</button></section>`;
}
